// Demo: Vulkan Compute Pipelines — kernel launch config math
var n=1*1024,threads=256;
var blocks=Math.ceil(n/threads);
console.log('technique: Vulkan Compute Pipelines');console.log('elements: '+n+', threads/block: '+threads);
console.log('blocks: '+blocks+', total threads: '+(blocks*threads));
console.log('occupancy: '+(100*n/(blocks*threads)).toFixed(1)+'% of launched threads do work');

